public class ElementalDamageUp : Item
{
	protected static string eleFieldStr = "elementType";

	protected static string subEleFieldStr = "subElementType";

	protected ElementType element;

	protected NumVarStatMod damageMod;

	protected string elementStr;

	protected string calcFieldStr;

	protected bool useSubElement;

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public ElementalDamageUp(string givenID, ElementType givenElement, float givenIncrease = 0.12f)
	{
		ID = givenID;
		category = Category.Offense;
		element = givenElement;
		elementStr = element.ToString();
		damageMod = new NumVarStatMod(ID, givenIncrease, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	public virtual void SetModStatus(bool givenStatus)
	{
		calcFieldStr = ((!useSubElement) ? eleFieldStr : subEleFieldStr);
		StatManager.ModifyAllStatData(damageMod, parentSkillCategory, "damage", AppliedCondition, givenStatus);
	}

	public virtual bool AppliedCondition(StatData givenStatData)
	{
		return !givenStatData.GetValue<bool>("isStatusEffect") && givenStatData.GetValue<string>(calcFieldStr) == elementStr;
	}
}
