using UnityEngine.SceneManagement;

public class DamageUpVsBoss : Item
{
	public static string staticID = "DamageUpVsBoss";

	private NumVarStatMod damageMod;

	private bool isBossScene;

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpVsBoss()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		damageMod = new NumVarStatMod(ID, 0.2f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		ApplyMods(givenStatus);
		SceneManager.sceneLoaded -= OnSceneLoaded;
		if (givenStatus)
		{
			SceneManager.sceneLoaded += OnSceneLoaded;
		}
	}

	private void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		ApplyMods(givenStatus: true);
	}

	private void ApplyMods(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			if (givenStatus)
			{
				isBossScene = NextLevelLoader.InBossScene(string.Empty);
				StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, isBossScene);
				parentPlayer.health.damageTakenStat.Modify(damageMod, !isBossScene);
			}
			else
			{
				StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, addMod: false);
				parentPlayer.health.damageTakenStat.RemoveMod(damageMod);
			}
		}
	}
}

