	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ThunderFanBall.prefab"));

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (atkDisabled)
		{
			atkDisabled = false;
			atkCollider.enabled = true;
		}
		if (!atkStopwatch.IsRunning)
		{
			atkStopwatch.IsRunning = true;
			atkDisabled = true;
			atkCollider.enabled = false;
		}
		if (!shootStopwatch.IsRunning)
		{
			shootStopwatch.IsRunning = true;
			shootIndex++;
			ShootThunderFan(Globals.GetRotatedCircleVector(shootPositions, shootIndex, -moveVector));
			if (shootIndex >= 24)
			{
				ResetProjectile();
			}
		}
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		CreateThunderFanBurst();
	}

	private void ShootThunderFan(Vector2 givenVector)
	{
		currentFP = Globals.ChaosInst<ThunderFanProjectile>(ThunderFanProjectile.Prefab, null, (Vector2)transform.position + givenVector);
		currentFP.parentEntity = parentEntity;
		currentFP.parentObject = parentObject;
		currentFP.attackBox.SetAttackInfo(shootAtkInfo);
		currentFP.moveVector = givenVector;
		currentFP.lerpSpeed = false;
		currentFP.isEmpowered = true;
		currentFP.empTrans = transform;
	}

	private void CreateThunderFanBurst()
	{
		SoundManager.PlayAudioWithDistance("ThunderClap", transform.position);
		LightningBurst.CreateBurst(transform.position, string.Empty, string.Empty, 1, 3.5f);
		for (int i = 0; i < shootPositions; i++)
		{
			ShootThunderFan(Globals.GetCirclePositionVector(shootPositions, i));
		}
	}
